#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        long long C, v;
        cin >> n >> C >> v;
        vector<long long> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i];

        long long mx = 0, mn = LLONG_MAX;
        bool hasZero = false;
        vector<long long> gap(n - 1);

        for (int i = 0; i + 1 < n; ++i) {
            long long diff = a[i + 1] - a[i];
            gap[i] = diff;
            mx = max(mx, diff);
            mn = min(mn, diff);
            if (diff > C) hasZero = true;
        }

        // 情况 0
        if (hasZero) {
            cout << 0 << '\n';
            continue;
        }

        // 情况 1
        if (mx + v > C || mn < v - C) {
            cout << 1 << '\n';
            continue;
        }

        // 情况 3
        long long ans = LLONG_MAX;
        for (int i = 0; i < n - 1; ++i) {
            long long diff = gap[i];
            long long need = (C - diff) / v + 1;
            if (need <= n - i - 1) {
                ans = min(ans, need);
            }
        }

        cout << (ans == LLONG_MAX ? -1 : ans) << '\n';
    }

    return 0;
}
